import axios from 'axios'
export default {
    data(){
        return{
            dialog: false,
            search:'',
            medidas:[],
            headers: [
                { text: 'Opciones', value: 'opciones', sortable: false },
                { text: 'Codigo', value: 'CodigoUnidad', sortable: true },
                { text: 'Descripción', value: 'Descripcion', sortable: false },
                { text: 'Simbolo', value: 'Simbolo', sortable: false }
            ],
            editedIndex: -1,
            CodigoUnidad:'',
            Descripcion:'',
            Simbolo:'',
            validaMensaje:[],
            adModal:0,
            adAccion:0,
            adNombre:'',
            adId:''
        }
    },
    computed: {
        formTitle () {
        return this.editedIndex === -1 ? 'Nuevo registro' : 'Editar registro'
        }
    },
    watch: {
        dialog (val) {
        val || this.close()
        }
    },
    created () {
        this.listar()
    },
    methods: {
        listar(){
            let me=this;
            axios.get('unidades/').then(function (response){
                me.medidas=response.data;
            }).catch(function(error){
                console.log(error);
            });

        },
        limpiar(){
            this.Descripcion='';
            this.Simbolo='';
            this.editedIndex=-1;
        },
        validar(){
            this.valida=0;
            this.validaMensaje=[];
            if(this.Descripcion.length<1 || this.Descripcion.length>50){
                this.validaMensaje.push('La descripcion de la unidad debe tener entre 1-50 caracteres.');
            }
            if(this.Simbolo.length>255){
                this.validaMensaje.push('El simbolo de la unodad no debe tener más de 255 caracteres.');
            }
            if (this.validaMensaje.length){
                this.valida=1;
            }
            return this.valida;
        },
        guardar(){
            let me=this;
            if (this.validar()){
                return;
            }
            if (this.editedIndex >-1){
                //Código para editar
              console.log(this.CodigoUnidad,this.Descripcion,this.Simbolo)
                axios.put('unidades/',{'CodigoUnidad':this.CodigoUnidad,'Descripcion':this.Descripcion,'Simbolo':this.Simbolo})
                .then(function(response){
                    me.limpiar();
                    me.close();
                    me.listar();
                })
                .catch(function(error){
                    console.log(error);
                }); 
            }else{
                axios.post('unidades/',{'Descripcion':this.Descripcion,'Simbolo':this.Simbolo})
                .then(function(response){
                    me.limpiar();
                    me.close();
                    me.listar();
                })
                .catch(function(error){
                    console.log(error);
                });
            }
        },
        editItem (item) {
            this.CodigoUnidad=item.CodigoUnidad;
            this.Descripcion=item.Descripcion;
            this.Simbolo=item.Simbolo;
            this.dialog = true;
            this.editedIndex=1;
        },
        activarDesactivarMostrar(accion,item){
            this.adModal=1;
            this.adNombre=item.Descripcion;
            this.adSimbolo = item.Simbolo;
            this.adId=item.CodigoUnidad;
            if (accion==1){
                this.adAccion=1;
            } else if(accion==2){
                this.adAccion=2;
            } else{
                this.adModal=0;
            }
        },
        activarDesactivarCerrar(){
            this.adModal=0;
        },
        activar(){
            let me=this;
            axios.put('unidades/',{'CodigoUnidad':this.adId})
                .then(function(response){
                    me.adModal=0;
                    me.adAccion=0;
                    me.adNombre='';
                    me.adSimbolo='';
                    me.adId='';
                    me.listar();
                })
                .catch(function(error){
                    console.log(error);
                });
        },
        desactivar(){
            let me=this;
            axios.put('unidades/deactivate',{'_id':this.adId})
                .then(function(response){
                    me.adModal=0;
                    me.adAccion=0;
                    me.adNombre='';
                    me.adId='';
                    me.listar();
                })
                .catch(function(error){
                    console.log(error);
                });
        },
        close () {
            this.dialog = false;
        }
    }
}
